-- Bersihkan EP lama bab MRMIK (akan diganti dengan data parse)
DELETE FROM starkes_ep WHERE bab = 'MRMIK';

INSERT IGNORE INTO starkes_ep (kd_ep, bab, nama_bab, kelompok, standar, nomor_ep,
                         deskripsi, jenis_bukti, prioritas, kategori_bukti) VALUES
('MRMIK.1.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.1', 1, 'Rumah sakit menetapkan regulasi pengelolaan informasi untuk memenuhi kebutuhan informasi sesuai poin a) – g) dalam gambaran umum.', 'R', 3, 'sop'),
('MRMIK.1.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.1', 2, 'Terdapat bukti rumah sakit telah menerapkan proses pengelolaan informasi untuk memenuhi kebutuhan PPA, pimpinan rumah sakit, kepala departemen/unit layanan dan badan/individu dari luar rumah sakit.', 'D,W', 2, 'sop'),
('MRMIK.1.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.1', 3, 'Proses yang diterapkan sesuai dengan ukuran rumah sakit, kompleksitas layanan, ketersediaan staf terlatih, sumber daya teknis, dan sumber daya lainnya.', 'W', 3, 'sop'),
('MRMIK.1.4', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.1', 4, 'Rumah sakit melakukan pemantauan dan evaluasi secara berkala sesuai ketentuan rumah sakit serta upaya perbaikan terhadap pemenuhan informasi internal dan eksternal.', 'D,W', 2, 'log'),
('MRMIK.1.5', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.1', 5, 'Apabila terdapat program penelitian dan atau pendidikan kesehatan, terdapat bukti bahwa data dan informasi yang mendukung asuhan pasien, pendidikan, serta riset telah tersedia tepat waktu.', 'D', 2, 'sop'),
('MRMIK.2.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 1, 'Terdapat bukti PPA, pimpinan rumah sakit, kepala departemen, unit layanan dan staf telah dilatih tentang prinsip pengelolaan dan penggunaan informasi sistem.', 'D,W', 2, 'sop'),
('MRMIK.2.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 2, 'Terdapat bukti bahwa data dan informasi klinis serta non klinis diintegrasikan sesuai kebutuhan dan digunakan dalam mendukung proses pengambilan keputusan.', 'D', 2, 'sop'),
('MRMIK.2.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 2, 'Rumah sakit menerapkan proses pemberian akses kepada staf yang berwenang untuk mengakses data dan informasi, termasuk entry ke dalam rekam medis pasien.', 'D,W', 3, 'laporan'),
('MRMIK.2.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 3, 'Rumah sakit memantau kepatuhan terhadap proses ini dan mengambil tindakan ketika terjadi pelanggaran terhadap kerahasiaan, keamanan, atau integritas data.', 'D,W', 3, 'sop'),
('MRMIK.2.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 2, 'Rumah sakit menerapkan pemantauan dan evaluasi terhadap keamanan data dan informasi.', 'D,W', 2, 'log'),
('MRMIK.2.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.2', 3, 'Terdapat bukti rumah sakit telah melakukan tindakan perbaikan untuk meningkatkan keamanan data dan informasi.', 'D', 2, 'sop'),
('MRMIK.3.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.3', 1, 'Rumah sakit menerapkan pengelolaan dokumen sesuai dengan butir a) - h) dalam maksud dan tujuan.', 'D,W', 3, 'sop'),
('MRMIK.3.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.3', 2, 'Rumah sakit memiliki dan menerapkan format yang seragam untuk semua dokumen sejenis sesuai dengan ketentuan rumah sakit.', 'D,W', 3, 'sop'),
('MRMIK.3.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.3', 3, 'Rumah sakit telah memiliki dokumen internal mencakup butir a) - c) dalam maksud dan tujuan.', 'D,W', 3, 'sop'),
('MRMIK.4.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.4', 1, 'Terdapat bukti bahwa penyebaran data dan informasi memenuhi kebutuhan internal dan eksternal rumah sakit sesuai dengan yang tercantum dalam maksud dan tujuan.', 'D', 2, 'sop'),
('MRMIK.4.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.4', 2, 'Terdapat proses yang memastikan bahwa data dan informasi yang dibutuhkan untuk perawatan pasien telah diterima tepat waktu dan sesuai format yang seragam dan sesuai dengan kebutuhan.', 'D', 3, 'sop'),
('MRMIK.5.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.5', 1, 'Rumah sakit telah menetapkan regulasi tentang penyelenggaraan rekam medis di rumah sakit.', 'R,D', 3, 'sop'),
('MRMIK.5.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.5', 2, 'Rumah sakit menetapkan unit penyelenggara rekam medis dan 1 (satu) orang yang kompeten mengelola rekam medis.', 'R,D', 3, 'sop'),
('MRMIK.5.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.5', 3, 'Rumah Sakit menerapkan penyelenggaraan Rekam Medis yang dilakukan sejak pasien masuk sampai pasien pulang, dirujuk, atau meninggal.', 'D', 3, 'laporan'),
('MRMIK.5.4', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.5', 4, 'Pengelolaan rekam medis yang menjamin keamanan dan kerahasiaannya, melalui penjaminan mutu secara berkala yang dilakukan oleh tim reviu yang ditetapkan oleh pimpinan rumah sakit.', 'D,W', 3, 'laporan'),
('MRMIK.6.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.6', 1, 'Rumah sakit menetapkan isi spesifik dari rekam medis dari setiap jenis pelayanan dan memastikan kelengkapan serta ketepatan waktu pengisiannya.', 'R,D', 3, 'sop'),
('MRMIK.6.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.6', 2, 'Rumah sakit menetapkan format yang seragam untuk semua jenis rekam medis (kertas dan atau elektronik), baik untuk rawat jalan, rawat inap, maupun gawat darurat.', 'R,D', 3, 'sop'),
('MRMIK.6.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.6', 3, 'Terdapat bukti rekam medis dievaluasi dan diperbaharui sesuai kebutuhan medis serta dikelola sejak dibuat, ditinjau, dievaluasi, disimpan, hingga dimusnahkan.', 'D', 2, 'log'),
('MRMIK.7.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.7', 1, 'Terdapat bukti rekam medis pasien telah berisi informasi yang sesuai dengan ketetapan rumah sakit dan peraturan perundangan yang berlaku', 'D', 2, 'laporan'),
('MRMIK.7.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.7', 2, 'Terdapat bukti rekam medis pasien mengandung informasi yang memadai sesuai butir a) – f) pada maksud dan tujuan', 'D', 2, 'laporan'),
('MRMIK.8.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.8', 1, 'PPA mencantumkan identitas secara jelas pada saat mengisi RM.', 'W', 3, 'sop'),
('MRMIK.8.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.8', 2, 'Tanggal dan waktu penulisan setiap catatan dalam rekam medis pasien dapat diidentifikasi.', 'D', 3, 'laporan'),
('MRMIK.8.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.8', 3, 'Terdapat prosedur koreksi penulisan dalam pengisian RM elektronik dan non elektronik.', 'D', 3, 'sop'),
('MRMIK.8.4', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.8', 4, 'Telah dilakukan pemantauan dan evaluasi terhadap penulisan identitas, tanggal dan waktu penulisan catatan pada rekam medis pasien serta koreksi penulisan catatan dalam rekam medis, dan hasil evaluasi yang ada telah digunakan sebagai dasar upaya perbaikan di rumah sakit.', 'D', 2, 'log'),
('MRMIK.9.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.9', 1, 'Penggunaan kode diagnosis, kode prosedur, singkatan dan simbol sesuai dengan ketetapan rumah sakit.', 'D,W', 3, 'sop'),
('MRMIK.9.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.9', 2, 'Dilakukan evaluasi secara berkala penggunaan kode diagnosis, kode prosedur, singkatan dan simbol yang berlaku di rumah sakit dan hasilnya digunakan sebagai upaya tindak lanjut untuk perbaikan.', 'D,W', 2, 'log'),
('MRMIK.10.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.10', 1, 'Rumah sakit menentukan otoritas pengisian rekam medis termasuk isi dan format rekam medis.', 'D', 3, 'laporan'),
('MRMIK.10.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.10', 2, 'Rumah Sakit menentukan hak akses dalam pelepasan informasi rekam medis', 'D', 3, 'laporan'),
('MRMIK.10.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.10', 3, 'Rumah sakit menjamin otentifikasi, keamanan dan kerahasiaan data rekam medis baik kertas maupun elektronik sebagai bagian dari hak pasien.', 'D', 3, 'laporan'),
('MRMIK.11.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.11', 1, 'Rumah sakit memiliki regulasi jangka waktu penyimpanan berkas rekam medis (kertas/elektronik), serta data dan informasi lainnya terkait dengan pasien dan prosedur pemusnahannya sesuai dengan peraturan perundangan', 'R,D', 3, 'sop'),
('MRMIK.11.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.11', 2, 'Dokumen, data dan/informasi terkait pasien dimusnahkan setelah melampaui periode waktu penyimpanan sesuai dengan peraturan perundang- undangan dengan prosedur yang tidak membahayakan keamanan dan kerahasiaan', 'D,W', 3, 'sop'),
('MRMIK.11.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.11', 3, 'Dokumen, data dan/atau informasi tertentu terkait pasien yang bernilai guna, disimpan abadi (permanen) sesuai dengan ketetapan rumah sakit', 'D,W', 3, 'sop'),
('MRMIK.12.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.12', 1, 'Rumah sakit menetapkan komite/tim rekam medis.', 'R,D', 3, 'sop'),
('MRMIK.12.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.12', 2, 'Komite/tim secara berkala melakukan pengkajian rekam medis pasien secara berkala setiap tahun dan menggunakan sampel yang mewakili (rekam medis pasien yang masih dirawat dan pasien yang sudah pulang).', 'D', 3, 'asesmen'),
('MRMIK.12.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.12', 3, 'Fokus pengkajian paling sedikit mencakup pada ketepatan waktu, keterbacaan, kelengkapan rekam medis dan isi rekam medis sesuai dengan peraturan perundangan', 'D', 3, 'asesmen'),
('MRMIK.12.4', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.12', 4, 'Hasil pengkajian yang dilakukan oleh komite/tim rekam medis dilaporkan kepada pimpinan rumah sakit dan dibuat upaya perbaikan', 'D,W', 3, 'asesmen'),
('MRMIK.13.1', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 1, 'Rumah sakit menetapkan regulasi tentang penyelenggaraan teknologi informasi kesehatan', 'R', 3, 'sop'),
('MRMIK.13.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 2, 'Rumah sakit menerapkan SIMRS sesuai dengan ketetapan dan peraturan perundangan yang berlaku.', 'D,W', 3, 'sop'),
('MRMIK.13.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 3, 'Rumah sakit menetapkan unit yang bertanggung jawab sebagai penyelenggara SIMRS dan dipimpin oleh staf kompeten', 'R,W', 3, 'sop'),
('MRMIK.13.4', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 4, 'Data serta informasi klinis dan non klinis diintegrasikan sesuai dengan kebutuhan untuk mendukung pengambilan keputusan.', 'D,W', 3, 'sop'),
('MRMIK.13.5', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 5, 'Rumah sakit telah menerapkan proses untuk menilai efektivitas sistem rekam medis elektronik dan melakukan upaya perbaikan terkait hasilpenilaian yang ada', 'D', 2, 'laporan'),
('MRMIK.13.2', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 2, 'Staf dilatih dan memahami perannya di dalam prosedur penanganan waktu henti sistem data (down time), baik yang terencana maupun yang tidak terencana.', 'W', 3, 'sop'),
('MRMIK.13.3', 'MRMIK', 'Manajemen Rekam Medis & Informasi Kesehatan', 1, 'MRMIK.13', 3, 'Rumah sakit melakukan evaluasi pasca terjadinya waktu henti sistem data (down time) dan menggunakan informasi dari data tersebut untuk persiapan dan perbaikan apabila terjadi waktu henti (down time) berikutnya.', 'D,W', 2, 'log');
